"""Core simulation entities: tasks and processing locations.

A *location* is any place a task can execute: the originating device itself
(``local``), one of the heterogeneous edge servers, or the remote cloud.
"""
from __future__ import annotations

from dataclasses import dataclass, field
from enum import Enum
from typing import Optional


class LocType(Enum):
    LOCAL = "local"
    EDGE = "edge"
    CLOUD = "cloud"


@dataclass
class Task:
    """A computational task generated by a device."""
    tid: int
    device: int               # originating device index
    arrival: float            # arrival time (s)
    demand: float             # compute demand (Mcyc)
    input_size: float         # input data size (Mb)
    output_size: float        # output data size (Mb)
    deadline: float           # absolute deadline time (s)
    priority: int             # 1 = normal, 2 = high
    local_capable: bool = True

    # ---- filled in during/after execution -------------------------------
    placement: Optional[str] = None     # location id string, e.g. "edge:2"
    start_time: Optional[float] = None
    finish_time: Optional[float] = None
    decision_time: float = 0.0          # wall-clock cost of scheduling decision (s)
    telemetry_used: int = 0             # # of telemetry probes spent for this task
    telemetry_bytes: float = 0.0        # Mb of telemetry spent for this task
    energy: float = 0.0                 # estimated joules for this task
    regret: float = 0.0                 # completion time - oracle completion time

    @property
    def completion_time(self) -> Optional[float]:
        if self.finish_time is None:
            return None
        return self.finish_time - self.arrival

    @property
    def deadline_met(self) -> Optional[bool]:
        if self.finish_time is None:
            return None
        return self.finish_time <= self.deadline


@dataclass
class Location:
    """A processing location with a dynamic, partially observable state.

    The *true* utilization ``u_true`` evolves in :mod:`environment`. The
    scheduler never reads ``u_true`` directly unless it spends telemetry; it
    works from an estimate held in :mod:`telemetry`.
    """
    loc_id: str                 # e.g. "local:3", "edge:0", "cloud"
    loc_type: LocType
    index: int                  # device/edge index (cloud = -1)
    capacity: float             # Mcyc/s processing speed
    compute_energy: float       # J per Mcyc
    u_true: float = 0.0         # true instantaneous utilization in [0,1)
    u_mean: float = 0.45        # stationary mean (for OU process)
    failed: bool = False

    def effective_time(self, demand: float) -> float:
        """Compute time for ``demand`` Mcyc given current true utilization.

        Uses an M/M/1-style sojourn scaling: the base service time is inflated
        by ``1/(1-u)`` to model contention/queueing, capped for stability.
        """
        if self.failed or self.capacity <= 0:
            return float("inf")
        u = min(max(self.u_true, 0.0), 0.95)
        return (demand / self.capacity) / (1.0 - u)
